/* Touch controls are presentation/input only. Physics, routes, seats and buses remain authoritative. */
function createMobile108(hooks){
 const coarse=matchMedia('(pointer:coarse)'),$=id=>document.getElementById(id),canvas=$('world');
 const root=document.createElement('section');root.id='mobile108';root.setAttribute('aria-label','터치 조작');
 root.innerHTML=`<div class="m108Tools"><img class="m108Brand124" src="assets/title105/logo.webp" alt="3NU" draggable="false"><button data-help aria-label="조작법"><span class="question124" aria-hidden="true">?</span> 조작법</button><button data-photo aria-label="사진 찍기">▣</button><button data-settings aria-label="설정">⚙</button></div>
 <div class="m108Guide"><button data-map class="m108Map"><strong data-zone></strong><small>지도 보기 ↗</small></button><section data-summary-card hidden><button data-summary aria-expanded="false"><small data-kicker></small><strong data-heading></strong><span aria-hidden="true">⌄</span></button><div data-detail hidden><p data-copy></p><button data-primary></button><button data-secondary></button></div></section></div>
 <div class="m108StickArea"><div class="m108Stick" role="group" aria-label="이동 조이스틱"><i></i><b></b></div><span>이동 · 바깥쪽으로 가속</span></div>
 <div class="m108Actions"><button data-context hidden></button><div data-vertical><button data-up></button><button data-down></button></div></div>`;
 document.body.append(root);const q=s=>root.querySelector(s),stick=q('.m108Stick'),knob=stick.querySelector('b');
 let enabled=false,last=0,signature='',expanded=false,mode='',stickId=null,look=null;const held=new Map(),captures=new Map();
 const text=(sel,value)=>{const n=q(sel);if(n.textContent!==String(value))n.textContent=value};
 function reset(){stickId=null;look=null;held.clear();const previous=[...captures];captures.clear();for(const [id,el]of previous)try{if(el.hasPointerCapture(id))el.releasePointerCapture(id)}catch{}knob.style.transform='';root.querySelectorAll('.pressed').forEach(n=>n.classList.remove('pressed'));hooks.move(0,0,false);hooks.vertical(false,false);}
 function layout(){reset();enabled=coarse.matches;document.body.classList.toggle('mobile108',enabled);root.hidden=!enabled;const v=visualViewport;document.documentElement.style.setProperty('--viewport108',(v?.height||innerHeight)+'px');signature='';}
 function usable(){const s=hooks.state();return enabled&&s.playing&&!s.blocked;}
 function begin(e){if(!usable())return false;e.preventDefault();try{e.currentTarget.setPointerCapture(e.pointerId);captures.set(e.pointerId,e.currentTarget)}catch{}return true;}
 function moveStick(e){if(e.pointerId!==stickId)return;const r=stick.getBoundingClientRect(),range=r.width*.34;let x=(e.clientX-r.left-r.width/2)/range,y=(e.clientY-r.top-r.height/2)/range,l=Math.hypot(x,y);x/=Math.max(1,l);y/=Math.max(1,l);knob.style.transform=`translate(${x*range}px,${y*range}px)`;hooks.move(x,-y,l>.8);}
 stick.addEventListener('pointerdown',e=>{if(stickId!==null||!begin(e))return;stickId=e.pointerId;moveStick(e)});stick.addEventListener('pointermove',moveStick);
 for(const type of ['pointerup','pointercancel','lostpointercapture'])stick.addEventListener(type,e=>{captures.delete(e.pointerId);if(e.pointerId!==stickId)return;stickId=null;knob.style.transform='';hooks.move(0,0,false)});
 function applyHeld(){hooks.vertical([...held.values()].includes('up'),[...held.values()].includes('down'));}
 for(const direction of ['up','down']){const b=q('[data-'+direction+']');b.addEventListener('pointerdown',e=>{if(!begin(e))return;held.set(e.pointerId,direction);b.classList.add('pressed');applyHeld()});for(const type of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(type,e=>{captures.delete(e.pointerId);if(!held.delete(e.pointerId))return;b.classList.toggle('pressed',[...held.values()].includes(direction));applyHeld()});}
 canvas.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch'||!usable()||look||e.clientX<innerWidth*.32)return;e.preventDefault();try{canvas.setPointerCapture(e.pointerId);captures.set(e.pointerId,canvas)}catch{}look={id:e.pointerId,x:e.clientX,y:e.clientY};});canvas.addEventListener('pointermove',e=>{if(!look||e.pointerId!==look.id)return;if(!usable()){reset();return}hooks.look(e.clientX-look.x,e.clientY-look.y);look={id:e.pointerId,x:e.clientX,y:e.clientY};});for(const type of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(type,e=>{captures.delete(e.pointerId);if(look?.id===e.pointerId)look=null});
 q('[data-settings]').onclick=()=>{hooks.clear();hooks.settings()};q('[data-photo]').onclick=()=>{hooks.clear();hooks.photo()};q('[data-map]').onclick=()=>{hooks.clear();hooks.map()};q('[data-help]').onclick=()=>{hooks.clear();hooks.help()};q('[data-context]').onclick=()=>{hooks.clear();hooks.action()};
 q('[data-summary]').onclick=()=>{expanded=!expanded;signature='';update(performance.now(),true)};q('[data-primary]').onclick=()=>{hooks.clear();hooks.primary();signature=''};q('[data-secondary]').onclick=()=>{hooks.clear();hooks.secondary();signature=''};
 function update(now,force=false){if(!enabled||(!force&&now-last<150))return;last=now;const s=hooks.state();if(s.blocked||!s.playing)reset();root.hidden=!s.playing||(s.blocked&&!s.guiding);if(root.hidden)return;const next=JSON.stringify([s.character,s.zone,s.riding,s.summary,s.action,expanded]);if(next===signature)return;signature=next;if(mode!==s.summary?.mode){mode=s.summary?.mode||'';expanded=false;}text('[data-zone]',s.zone||'서울대학교');text('[data-up]',s.character==='baekhak'?'상승':'점프');text('[data-down]',s.character==='baekhak'?'하강':'웅크리기');q('.m108StickArea').hidden=s.riding;q('[data-vertical]').hidden=s.riding;q('[data-context]').hidden=!s.action;text('[data-context]',s.action||'');q('[data-summary-card]').hidden=!s.summary;if(s.summary){text('[data-kicker]',s.summary.kicker);text('[data-heading]',s.summary.title);text('[data-copy]',s.summary.copy);text('[data-primary]',s.summary.primary);text('[data-secondary]',s.summary.secondary);q('[data-primary]').hidden=!s.summary.primary;q('[data-secondary]').hidden=!s.summary.secondary;q('[data-summary]').setAttribute('aria-expanded',String(expanded));q('[data-detail]').hidden=!expanded;}}
 for(const ev of ['blur','pagehide','resize','orientationchange'])window.addEventListener(ev,layout);document.addEventListener('visibilitychange',reset);visualViewport?.addEventListener('resize',layout);coarse.addEventListener('change',layout);layout();
 return{get enabled(){return enabled},get busy(){return !!hooks.helpOpen?.()},clear:reset,update,audit:()=>({enabled,stickId,lookId:look?.id??null,held:[...held.values()],expanded,mode})};
}
